def solve(rows):
    from collections import defaultdict

    region_data = defaultdict(lambda: {"delivered": 0, "total": 0})

    for row in rows:
        if row["quantity"] >= 5:
            region = row["region"]
            status = row["status"]
            region_data[region]["total"] += 1
            if status == "delivered":
                region_data[region]["delivered"] += 1

    result = []
    for region, data in region_data.items():
        delivered = data["delivered"]
        total = data["total"]
        if total > 0:
            percentage = round(100 * delivered / total, 1)
            if percentage >= 30:
                result.append([region, percentage])

    result.sort(key=lambda x: (-x[1], x[0]))
    return result
```

