def solve(rows):
    filtered_rows = [row for row in rows if row["quantity"] >= 5]
    region_sums = {}

    for row in filtered_rows:
        region = row["region"]
        quantity = row["quantity"]
        unit_price = row["unit_price"]
        total = quantity * unit_price
        if region in region_sums:
            region_sums[region] += total
        else:
            region_sums[region] = total

    if not region_sums:
        return None

    max_sum = -1
    max_region = None

    for region, total in region_sums.items():
        if total > max_sum or (total == max_sum and region < max_region):
            max_sum = total
            max_region = region

    return max_region
